import{_ as o,o as i,c as t,a4 as s}from"./chunks/framework.DPU9SBEx.js";const m=JSON.parse('{"title":"Pipeline Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md"}'),r={name:"guide/overview.md"};function c(n,e,a,l,d,p){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="pipeline-overview" tabindex="-1">Pipeline Overview <a class="header-anchor" href="#pipeline-overview" aria-label="Permalink to &quot;Pipeline Overview&quot;">​</a></h1><p>Komerce Design is a local-first, VCS-agnostic pipeline bridging design systems in Figma directly to universal Mitosis sources (<code>src/*</code>) and standalone multi-framework packages (<code>library/*</code>).</p><h2 id="end-to-end-local-workflow" tabindex="-1">End-to-End Local Workflow <a class="header-anchor" href="#end-to-end-local-workflow" aria-label="Permalink to &quot;End-to-End Local Workflow&quot;">​</a></h2><p>The workflow consists of four stages:</p><ol><li><p><strong>Extraction (<code>packages/figma-plugin</code>)</strong>:</p><ul><li>Runs as a native Figma Desktop plugin (<code>figma.loadAllPagesAsync()</code>).</li><li>Extracts local variables (color, spacing, numbers), paint styles, text styles, and component sets.</li><li>Supports <strong>Export Extraction JSON ⬇</strong> (100% serverless) or <strong>1-Click Local Sync</strong> against <code>pnpm komerce listen</code> (<code>http://127.0.0.1:8080</code>).</li></ul></li><li><p><strong>Deterministic Pre-Compiler &amp; Mitosis Authoring (<code>packages/mitosis-author</code>)</strong>:</p><ul><li>Translates Figma Auto Layout geometry, <code>boundVariables</code>, and canonical variant properties into a deterministic Tailwind/Mitosis blueprint before invoking the LLM (<code>LLM_PROVIDER=agy</code> or <code>openai</code>).</li><li>Edits universal Mitosis <code>.lite.tsx</code> JSX components in <code>src/components/*.lite.tsx</code> and <code>src/icons/*.lite.tsx</code> using pure headless state helpers (<code>src/components/utils.ts</code>) and semantic design tokens (<code>src/tokens/*</code>).</li><li>Feeds compiler, linter, and TypeScript diagnostics back into the LLM in a stateful cross-attempt repair loop.</li></ul></li><li><p><strong>Multi-Target Compilation &amp; Quality Gate (<code>packages/mitosis-compiler</code> &amp; <code>scripts/compile-library.mjs</code>)</strong>:</p><ul><li>Normalizes Mitosis AST patterns, enforces Tier 3 and cross-framework portability rules, and verifies in-memory TypeScript types.</li><li>Compiles <code>src/{components,icons}/*.lite.tsx</code> and copies <code>src/tokens/*</code> into standalone workspace packages under <code>library/*</code>: <ul><li><strong><code>@komerce-design/tokens</code></strong> (<code>library/tokens</code>)</li><li><strong><code>@komerce-design/react</code></strong> (<code>library/react</code> — <code>.tsx</code>)</li><li><strong><code>@komerce-design/vue3</code></strong> (<code>library/vue3</code> — Composition API <code>.vue</code>)</li><li><strong><code>@komerce-design/svelte</code></strong> (<code>library/svelte</code> — <code>.svelte</code>)</li><li><strong><code>@komerce-design/vue2</code></strong> (<code>library/vue2</code> — Options API <code>.vue</code>)</li><li><strong><code>@komerce-design/angular</code></strong> (<code>library/angular</code> — <code>@Component</code> + <code>@NgModule</code> <code>.ts</code>)</li></ul></li></ul></li><li><p><strong>Local Review &amp; Targeted Regeneration (<code>apps/docs</code> &amp; <code>pnpm komerce regen</code>)</strong>:</p><ul><li><strong>Live Multi-Framework Preview (<code>make review</code>)</strong>: Inspect all 5 frameworks side-by-side in isolated iframes at <code>http://localhost:5173</code>.</li><li><strong>Instant CLI Revision</strong>: Run <code>pnpm komerce regen &lt;Component&gt; &quot;&lt;notes&gt;&quot;</code> to re-author a single component in-place and recompile <code>library/*</code> + docs.</li><li><strong>VCS-Agnostic Git Push</strong>: Commit <code>src/*</code> and push to <strong>GitLab</strong>, <strong>GitHub</strong>, or any Git remote.</li></ul></li></ol>',5)])])}const u=o(r,[["render",c]]);export{m as __pageData,u as default};
